#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int main() {
    int num1, num2;
    scanf("%d%d", &num1, &num2);
    int result = add(num1, num2);
    printf("The sum of the two numbers is: %d\n", result);
    return 0;
}

#include <stdio.h>

int calculateCube(int num);

int main() {
    int num;
    scanf("%d", &num);
    printf("The cube of %d is: %d\n", num, calculateCube(num));
    return 0;
