int calculateCube(int num) {
    return num * num * num;
}

#include <stdio.h>

int isEven(int n) {
    return n % 2 == 0;
}

int main() {
    int n;
    scanf("%d", &n);
    if (isEven(n)) printf("The number is Even\n");
    else printf("The number is Odd\n");
    return 0;
}

#include <stdio.h>

int power(int base, int exponent) {
    int result = 1;
    for (int i = 0; i < exponent; i++) result *= base;
    return result;
}

int main() {
    int base, exponent;
    scanf("%d%d", &base, &exponent);
    printf("%d to the power of %d is: %d\n", base, exponent, power(base, exponent));
    return 0;
}

#include <stdio.h>
#include <math.h>

int isPrime(int num) {
    if (num < 2) return 0;
    for (int i = 2; i <= sqrt(num); i++) if (num % i == 0) return 0;
    return 1;
}

int main() {
    int N;
    scanf("%d", &N);
    printf("Prime numbers up to %d: ", N);
    for (int i = 2; i <= N; i++) if (isPrime(i)) printf("%d ", i);
    printf("\n");
    return 0;
}

#include <stdio.h>

int findGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int a, b;
    scanf("%d%d", &a, &b);
    printf("The GCD of %d and %d is: %d\n", a, b, findGCD(a, b));
    return 0;
}

#include <stdio.h>

int factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n-1);
}

int main() {
    int n;
    scanf("%d", &n);
    printf("The factorial of %d is: %d\n", n, factorial(n));
    return 0;
}

#include <stdio.h>

void modifyValue(int num) {
    num = 10;
}

int main() {
    int myNum = 5;
    printf("Initial value of myNum: %d\n", myNum);
    modifyValue(myNum);
    printf("Value of myNum after calling modifyValue: %d\n", myNum);
    return 0;
}

#include <stdio.h>

float metersToFeet(float meters) {
    return meters * 3.28084f;
}
float kgToPounds(float kg) {
    return kg * 2.20462f;
}

int main() {
    float meters, kg;
    scanf("%f%f", &meters, &kg);
    printf("%.2f meters is equivalent to %.2f feet.\n", meters, metersToFeet(meters));
    printf("%.2f kg is equivalent to %.2f pounds.\n", kg, kgToPounds(kg));
    return 0;
}
